import React, { useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import api from '../api/axios';
import toast from 'react-hot-toast';
import styles from './Checkout.module.css';

export default function Checkout() {
  const { state } = useLocation();
  const navigate = useNavigate();
  const [method, setMethod] = useState('card');
  const [loading, setLoading] = useState(false);

  if (!state) return <p className={styles.loading}>No booking data found.</p>;
  const { showtime, selectedSeats, totalAmount } = state;

  const handlePayment = async () => {
    setLoading(true);
    try {
      // Step 1: Create booking
      const { data: booking } = await api.post('/bookings', {
        showtimeId: showtime._id,
        seats: selectedSeats,
      });

      // Step 2: Process payment
      await api.post('/payments', { bookingId: booking._id, method });

      toast.success('Booking confirmed!');
      navigate(`/booking/${booking._id}/confirmation`);
    } catch (err) {
      toast.error(err.response?.data?.message || 'Payment failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className={styles.container}>
      <h2>Checkout</h2>

      <div className={styles.grid}>
        <div className={styles.summary}>
          <h3>Booking Summary</h3>
          <p><strong>Movie:</strong> {showtime.movie?.title}</p>
          <p><strong>Theater:</strong> {showtime.theater} — {showtime.screen}</p>
          <p><strong>Date & Time:</strong> {showtime.date} at {showtime.startTime}</p>
          <p><strong>Seats:</strong> {selectedSeats.map((s) => s.seatNumber).join(', ')}</p>
          <div className={styles.breakdown}>
            {selectedSeats.map((s) => (
              <div key={s.seatNumber} className={styles.seatRow}>
                <span>{s.seatNumber} ({s.type})</span>
                <span>₹{s.price}</span>
              </div>
            ))}
          </div>
          <div className={styles.total}>
            <span>Total</span>
            <span>₹{totalAmount}</span>
          </div>
        </div>

        <div className={styles.payment}>
          <h3>Payment Method</h3>
          {['card', 'upi', 'netbanking'].map((m) => (
            <label key={m} className={styles.option}>
              <input type="radio" value={m} checked={method === m} onChange={() => setMethod(m)} />
              {m === 'card' ? '💳 Credit / Debit Card' : m === 'upi' ? '📱 UPI' : '🏦 Net Banking'}
            </label>
          ))}

          {method === 'card' && (
            <div className={styles.cardForm}>
              <input placeholder="Card Number" maxLength={19} className={styles.input} />
              <div className={styles.row}>
                <input placeholder="MM/YY" className={styles.input} />
                <input placeholder="CVV" maxLength={3} className={styles.input} />
              </div>
              <input placeholder="Cardholder Name" className={styles.input} />
            </div>
          )}

          <button className={styles.btn} onClick={handlePayment} disabled={loading}>
            {loading ? 'Processing...' : `Pay ₹${totalAmount}`}
          </button>
          <p className={styles.note}>* This is a demo — no real payment is processed</p>
        </div>
      </div>
    </div>
  );
}
